pending: list = []

def copy_token_to_repeater(s, l, t):
    # drop stale entries left by abandoned or earlier parses
    while pending and pending[-1][0] >= l:
        pending.pop()
    pending.append((l, _flatten(t.as_list())))

def must_match_these_tokens(s, l, t):
